  static final String CAMPUS="61000000-0000-0000-0000-000000000001", OWNER="61000000-0000-0000-0000-000000000011", TARGET="61000000-0000-0000-0000-000000000012", OTHER="61000000-0000-0000-0000-000000000013", REPORTER="61000000-0000-0000-0000-000000000014", ADMIN="61000000-0000-0000-0000-000000000015";
